import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, PointLight, MathUtils } = ctx.THREE;

  const root = new Group();
  const stage = new Group();
  root.add(stage);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const find = (role) => items.find((i) => i.role === role);

  const cardW = 2.4, cardH = 3.2, cornerR = 0.06;
  const padX = -cardW / 2 + 0.5; // -0.7, left content edge

  const featureCenterYs = [0.10, -0.22, -0.54, -0.86];
  const ctaY = -1.22;

  // Disposables
  const geos = [];
  const mats = [];
  const tls = [];

  // ---- Local rim/accent light (scene provides ambient 0.6 + key 1.2) ----
  const rim = new PointLight(new Color('#ff2a38'), 1.5, 10, 2);
  rim.position.set(2.6, -0.4, 2.0);
  root.add(rim);

  // ---- Backdrop plane (~7x6 @ z=-2.5, engineered vertical gradient) ----
  const bgGeo = new PlaneGeometry(7, 6);
  geos.push(bgGeo);
  const bgMat = new MeshStandardNodeMaterial({
    color: new Color('#0b0b10'),
    roughness: 0.95,
    metalness: 0.0,
  });
  mats.push(bgMat);
  // Subtle engineered dark gradient: ink-tinted warm at top -> near-black cool at bottom.
  const top = vec3(0.045, 0.030, 0.040);
  const bot = vec3(0.035, 0.035, 0.050);
  bgMat.emissiveNode = mix(top, bot, uv().y);
  bgMat.emissiveIntensity = 0.35;
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.z = -2.5;
  root.add(bg);

  // ---- Outer hairline frame (perimeter border color, width ~0.006) ----
  const frameGeo = new PlaneGeometry(cardW + 0.012, cardH + 0.012);
  geos.push(frameGeo);
  const frameMat = new MeshBasicNodeMaterial({ color: new Color('#2a2a33') });
  mats.push(frameMat);
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = -0.01;
  stage.add(frame);

  // ---- Card body (surface) with rounded corners via TSL alpha ----
  const cardGeo = new PlaneGeometry(cardW, cardH);
  geos.push(cardGeo);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color('#16161d'),
    roughness: 0.62,
    metalness: 0.08,
  });
  mats.push(cardMat);

  const NW = uniform(cardW);
  const NH = uniform(cardH);
  const halfN = vec2(NW, NH).mul(0.5);
  const px = uv().sub(0.5).mul(2.0).mul(halfN);
  const dx = px.x.abs().sub(NW.mul(0.5).sub(cornerR));
  const dy = px.y.abs().sub(NH.mul(0.5).sub(cornerR));
  const cd = dx.max(0).pow(2).add(dy.max(0).pow(2)).sqrt();
  cardMat.alphaNode = smoothstep(cornerR + 0.004, cornerR - 0.004, cd);
  cardMat.transparent = true;
  // Slight emissive to keep contact lit, not flat-dead.
  cardMat.emissive = new Color('#08080d');
  cardMat.emissiveIntensity = 0.25;
  const card = new Mesh(cardGeo, cardMat);
  stage.add(card);

  // ---- Machined header strip at top edge ----
  const hsGeo = new PlaneGeometry(cardW, 0.08);
  geos.push(hsGeo);
  const hsMat = new MeshStandardNodeMaterial({
    color: new Color('#1f1f27'),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.6,
  });
  mats.push(hsMat);
  const hs = new Mesh(hsGeo, hsMat);
  hs.position.set(0, cardH / 2 - 0.04, 0.001);
  stage.add(hs);

  // ---- Feature hairline separators (#23232b, 0.006) ----
  const hairMat = new MeshBasicNodeMaterial({ color: new Color('#23232b') });
  mats.push(hairMat);
  const hairGeoCache = new PlaneGeometry(1.4, 0.006);
  geos.push(hairGeoCache);
  for (let i = 0; i < featureCenterYs.length - 1; i++) {
    const sepY = (featureCenterYs[i] + featureCenterYs[i + 1]) / 2;
    const line = new Mesh(hairGeoCache, hairMat);
    line.position.set(0, sepY, 0.001);
    stage.add(line);
  }

  // ---- CTA perimeter emissive ring ----
  const ringGeo = new PlaneGeometry(1.4 + 0.024, 0.36 + 0.024);
  geos.push(ringGeo);
  const ringMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.5,
    roughness: 0.5,
    metalness: 0.0,
  });
  mats.push(ringMat);
  const ring = new Mesh(ringGeo, ringMat);
  ring.position.set(0, ctaY, 0.0005);
  stage.add(ring);

  // ---- CTA button face with engineered vertical gradient ----
  const ctaGeo = new PlaneGeometry(1.4, 0.36);
  geos.push(ctaGeo);
  const ctaMat = new MeshBasicNodeMaterial();
  mats.push(ctaMat);
  // Gradient #ff4450 (at y=0, bottom) -> #c1121f (at y=1, top). Spec lists 0.0 then 1.0;
  // map uv().y=0 -> #ff4450, uv().y=1 -> #c1121f so accent stays warm at top.
  ctaMat.colorNode = mix(
    vec3(1.0, 0.2667, 0.3137), // #ff4450
    vec3(0.7569, 0.0706, 0.122), // #c1121f
    uv().y
  );
  const cta = new Mesh(ctaGeo, ctaMat);
  cta.position.set(0, ctaY, 0.001);
  stage.add(cta);

  // ---- Text via MSDF fontAtlas ----
  function addText(role, x, y, opts) {
    const item = find(role);
    if (!item) return null;
    const obj = ctx.fontAtlas.createText(String(item.text), opts);
    if (!obj) return null;
    obj.position.set(x, y, 0.002);
    obj.traverse((o) => {
      if (o.material) {
        // ensure transparent for fade animation
        if (Array.isArray(o.material)) {
          o.material.forEach((m) => { m.transparent = true; });
        } else {
          o.material.transparent = true;
        }
      }
    });
    stage.add(obj);
    return obj;
  }

  const tierName = addText('tier-name', padX, 1.10, {
    fontSize: 20, color: '#e8ecf2', align: 'left', letterSpacingPx: 0.08 * 20,
  });
  const price = addText('price', padX, 0.78, {
    fontSize: 62, color: '#e8ecf2', align: 'left', letterSpacingPx: -0.01 * 62,
  });
  const caption = addText('caption', padX, 0.54, {
    fontSize: 9, color: '#9aa0ad', align: 'left', letterSpacingPx: 0.12 * 9,
  });

  const featureObjs = [];
  for (let i = 0; i < 4; i++) {
    const o = addText('feature', padX, featureCenterYs[i], {
      fontSize: 13, color: '#c6ccda', align: 'left', letterSpacingPx: 0,
    });
    if (o) featureObjs.push(o);
  }

  const ctaLabel = addText('cta-label', 0, ctaY, {
    fontSize: 13, color: '#16161d', align: 'center', letterSpacingPx: 0.08 * 13,
  });

  // ---- Entrance: weighted-settle on stage ----
  stage.scale.setScalar(1.04);
  stage.position.z = 0.0;

  const settleTl = gsap.timeline();
  settleTl.to(stage.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });
  tls.push(settleTl);

  // Specular band drag: small rotational settle ~0.4 deg that drags the rim highlight
  // over the machined header during the settle, then settles flat.
  stage.rotation.y = 0.012;
  settleTl.to(stage.rotation, { y: 0, duration: 0.9, ease: 'cubic-bezier(0.165,0.84,0.44,1)' }, 0);

  // ---- Feature stagger fade-up ----
  const featTl = gsap.timeline({ delay: 0.22 });
  featureObjs.forEach((o, i) => {
    const baseY = o.position.y;
    o.position.y = baseY + 0.2;
    let mats = [];
    o.traverse((m) => {
      if (m.material) {
        if (Array.isArray(m.material)) {
          m.material.forEach((mm) => {
            mm.opacity = 0;
            mats.push(mm);
          });
        } else {
          m.material.opacity = 0;
          mats.push(m.material);
        }
      }
    });
    featTl.to(o.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, i * 0.08);
    mats.forEach((m) => {
      featTl.to(m, { opacity: 1, duration: 0.5, ease: 'power2.out' }, i * 0.08);
    });
  });
  tls.push(featTl);

  // Also fade tier-name / price / caption / cta label in alongside.
  [tierName, price, caption, ctaLabel].forEach((o) => {
    if (!o) return;
    let m2 = [];
    o.traverse((m) => {
      if (m.material) {
        if (Array.isArray(m.material)) {
          m.material.forEach((mm) => { mm.opacity = 0; m2.push(mm); });
        } else {
          m.material.opacity = 0;
          m2.push(m.material);
        }
      }
    });
    m2.forEach((m) => {
      featTl.to(m, { opacity: 1, duration: 0.55, ease: 'power2.out' }, 0);
    });
  });

  // ---- CTA press handler (attached to root.userData.handlers) ----
  root.userData.handlers = {
    pointerdown: (e) => {
      // Trigger if event hit the CTA mesh; otherwise ignore.
      const hit = e?.object ?? null;
      if (hit !== cta) return;
      gsap.to(cta.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
      gsap.to(cta.scale, {
        x: 1.0, y: 1.0, duration: 0.20, ease: 'power3.out', delay: 0.12,
      });
      gsap.to(ctaLabel.position, { y: ctaY, duration: 0.18, ease: 'power2.out' });
    },
    click: (e) => {
      if (e?.object !== cta) return;
      ctx.emit('navigate', { to: 'hub-pricing' });
    },
  };

  // ---- Hover tilt (subtle) ----
  root.userData.handlers.hover = (e) => {
    if (e?.object !== cta) return;
    gsap.to(stage.rotation, { y: 0.02, x: 0.005, duration: 0.3, ease: 'power2.out' });
    gsap.to(stage.rotation, { y: stage.rotation.y >= 0 ? 0.0 : 0, duration: 0.3, ease: 'power2.out', delay: 0.4 });
  };

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    tls.forEach((t) => { try { t.kill(); } catch (_) {} });
    geos.forEach((g) => { try { g.dispose(); } catch (_) {} });
    mats.forEach((m) => { try { m.dispose(); } catch (_) {} });
    try { rim.dispose && rim.dispose(); } catch (_) {}
    try { textObjs.forEach(o => o.traverse?.(child => {
      if (child.geometry) child.geometry.dispose?.();
      if (child.material) Array.isArray(child.material) ? child.material.forEach(mm => mm.dispose?.()) : child.material.dispose?.();
    })); } catch (_) {}
  };

  const textObjs = [tierName, price, caption, ctaLabel, ...featureObjs].filter(Boolean);

  return root;
}
